// architecture infers invariant rather than the weaker decision default.
var factKindPriority = map[string]int{
	factKindClosedNegative: 6,
	factKindGotcha:         5,
	factKindInvariant:      4,
	factKindPreference:     3,
	factKindConvention:     2,
	factKindDecision:       1,
